-- Disposable test DB only. No hosted Auth/Storage or real accounts.
begin;
insert into auth.users(id) values('11111111-1111-1111-1111-111111111111'),('22222222-2222-2222-2222-222222222222');
update daily_deck_private.auth_configuration set mode='preview';
create function test_support.cloud(op text,args jsonb default '{}',rev bigint default null,req uuid default gen_random_uuid()) returns jsonb language sql as $$
 select public.daily_deck_sync(auth.uid(),op,req,coalesce(rev,(select revision from public.daily_deck_sync_heads where owner_id=auth.uid()),0),case when op='read' then args else args||jsonb_build_object('localDay',current_date::text) end,'UTC')
$$;
grant execute on function test_support.cloud(text,jsonb,bigint,uuid) to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111111',true);
select public.daily_deck_complete_preview_onboarding(auth.uid(),true,true,false);
select test_support.assert_true((test_support.cloud('read')->'deck'->'tasks')='[]','fresh cloud is empty, no local starter upload');
select test_support.expect_error($q$insert into public.daily_deck_items(kind,title,created_on) values ('today','bypass',current_date)$q$,array['42501'],'direct item insert revoked');
select test_support.expect_error($q$update public.daily_deck_items set title='bypass'$q$,array['42501'],'column update grants revoked');
select test_support.expect_error('insert into public.daily_deck_events default values',array['42501'],'direct history writes revoked');
select test_support.expect_error('select daily_deck_private.reconcile(auth.uid(),current_date)',array['42501'],'private helpers are not callable by clients');
select test_support.expect_error($q$select public.daily_deck_sync('22222222-2222-2222-2222-222222222222','read',gen_random_uuid(),0,'{}','UTC')$q$,array['42501'],'spoofed RPC user denied');
select test_support.expect_error($q$select public.daily_deck_sync(auth.uid(),'read',gen_random_uuid(),0,'{}','invalid/timezone')$q$,array['22023'],'invalid timezone denied');
select set_config('test.req',gen_random_uuid()::text,true);
select set_config('test.create',jsonb_build_object('task',jsonb_build_object('id','aaaaaaaa-0000-0000-0000-000000000001','kind','habit','title','Daily test','notes','private A','minutes',null,'weekdays',jsonb_build_array(extract(dow from current_date)::int),'icon','water','deadline','14:00','remind',true))::text,true);
select set_config('test.saved',test_support.cloud('save',current_setting('test.create')::jsonb,0,current_setting('test.req')::uuid)::text,true);
select test_support.assert_true(jsonb_array_length(current_setting('test.saved')::jsonb->'deck'->'cards')=1,'selected weekday creates exactly one immediate occurrence');
select test_support.assert_true((test_support.cloud('save',current_setting('test.create')::jsonb,0,current_setting('test.req')::uuid)->>'revision')::bigint=1,'same request replays without duplicate write');
select test_support.expect_error($q$select test_support.cloud('save',current_setting('test.create')::jsonb||'{"extra":true}'::jsonb,0,current_setting('test.req')::uuid)$q$,array['23505'],'request ID cannot change payload');
select test_support.expect_error('select test_support.cloud(''save'',current_setting(''test.create'')::jsonb,0)',array['40001'],'stale second-device write rejected');
select test_support.assert_true(jsonb_array_length(test_support.cloud('read')->'deck'->'cards')=1,'repeated reconciliation does not duplicate');
select set_config('test.card',(test_support.cloud('read')->'deck'->'cards'->0->>'id'),true);
select test_support.cloud('action',jsonb_build_object('cardId',current_setting('test.card'),'action','later'));
select test_support.assert_true((select deadline_local=time '14:00' and remind_30_min from public.daily_deck_occurrences),'Later preserves deadline and reminder preference');
select set_config('test.undo',(select id::text from public.daily_deck_events order by sequence desc limit 1),true);
select test_support.cloud('undo',jsonb_build_object('eventId',current_setting('test.undo')));
select test_support.assert_true((select count(*)=2 from public.daily_deck_events),'Undo appends instead of removing action history');
select test_support.cloud('action',jsonb_build_object('cardId',current_setting('test.card'),'action','done'));
select set_config('test.done',(select occurred_at::text from public.daily_deck_events where action='done'),true);
select test_support.assert_true(jsonb_array_length(test_support.cloud('read')->'deck'->'cards')=1,'completed occurrence never regenerates');
select test_support.expect_error('select test_support.cloud(''action'',jsonb_build_object(''cardId'',current_setting(''test.card''),''action'',''done''))',array['40001'],'duplicate completion with new request cannot affect another card');
select test_support.cloud('delete','{"taskId":"aaaaaaaa-0000-0000-0000-000000000001"}');
select test_support.assert_true((select count(*)=1 from public.daily_deck_events where action='done' and occurred_at::text=current_setting('test.done')),'deletion retains completion timestamp');
select test_support.assert_true((select archived from public.daily_deck_items),'habit archive frees active slot');
select test_support.cloud('read');
select test_support.assert_true((select count(*)=1 from public.daily_deck_occurrences),'archived habit never regenerates');
select test_support.expect_error('select test_support.cloud(''save'',current_setting(''test.create'')::jsonb)',array['23514'],'deleted definition cannot be revived');
select test_support.expect_error('select test_support.cloud(''import'',''{"deck":{"version":1,"tasks":[],"cards":[]}}'')',array['23514'],'nonempty cloud import cannot merge or replace');
-- Second approved user cannot borrow IDs or read the first user's data.
select set_config('request.jwt.claim.sub','22222222-2222-2222-2222-222222222222',true);
select test_support.expect_error('select test_support.cloud(''read'')',array['42501'],'onboarding remains required for sync');
select public.daily_deck_complete_preview_onboarding(auth.uid(),true,true,false);
select test_support.assert_true((select count(*)=0 from public.daily_deck_items),'B cannot read A items');
select test_support.assert_true((select count(*)=0 from public.daily_deck_events),'B cannot read A history');
select test_support.assert_true((test_support.cloud('read')->'deck'->'tasks')='[]','B snapshot has no A data');
select test_support.expect_error('select test_support.cloud(''delete'',''{"taskId":"aaaaaaaa-0000-0000-0000-000000000001"}'')',array['40001'],'B cannot archive A ID');
select test_support.expect_error('select test_support.cloud(''action'',jsonb_build_object(''cardId'',current_setting(''test.card''),''action'',''done''))',array['40001'],'B cannot complete A occurrence');
select test_support.expect_error('select test_support.cloud(''undo'',jsonb_build_object(''eventId'',current_setting(''test.undo'')))',array['40001'],'B cannot undo A event');
select test_support.cloud('import','{"deck":{"version":1,"tasks":[],"cards":[]}}');
select test_support.expect_error('select test_support.cloud(''import'',''{"deck":{"version":1,"tasks":[],"cards":[]}}'')',array['23514'],'completed empty import cannot be silently replaced later');
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111111',true);
select test_support.assert_true((select count(*)=1 from public.daily_deck_items),'A cannot read B records');
reset role;
set local role anon;
select test_support.expect_error($q$select public.daily_deck_sync(null,'read',gen_random_uuid(),0,'{}','UTC')$q$,array['42501'],'anonymous sync RPC denied');
select test_support.expect_error('select * from public.daily_deck_sync_heads',array['42501'],'anonymous cache-head read denied');
select test_support.expect_error('select public.daily_deck_photo(null,gen_random_uuid())',array['42501'],'anonymous photo RPC denied');
reset role;
rollback;
